pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 deposit1, uint256 deposit2, uint256 cashOutAmount) public {
        // Keep deposits reasonable to avoid overflow in balances sum
        deposit1 = bound(deposit1, 1 ether, 1000 ether);
        deposit2 = bound(deposit2, 1 ether, 1000 ether);
        cashOutAmount = bound(cashOutAmount, 1, deposit1 + deposit2);

        address actor = address(0x100);
        vm.deal(actor, deposit1 + deposit2);

        // First deposit
        vm.prank(actor);
        c.Deposit{value: deposit1}();
        uint256 balanceAfterFirst = c.balances(actor);

        // Second deposit (the one that triggers the bug in M when Deposit is called again before CashOut?)
        // Actually, the bug is in Deposit: balances[msg.sender] = 0 before += msg.value every time.
        // To expose the difference, we need a CashOut that relies on previous deposits not being erased.
        vm.prank(actor);
        c.Deposit{value: deposit2}();
        uint256 balanceAfterSecond = c.balances(actor);

        // Record expected balance: deposit1 + deposit2 (correct) vs only deposit2 (bug)
        // In correct C: after two deposits, balance = deposit1 + deposit2.
        // In mutant M: after second deposit, balance = deposit2 because deposit1 was reset to 0.
        uint256 beforeCashOut = c.balances(actor);
        require(beforeCashOut > 0, "balance must be positive");

        // Now perform CashOut of an amount that reveals the discrepancy.
        // The actor withdraws cashOutAmount (<= deposit1+deposit2) which should succeed in both.
        vm.prank(actor);
        c.CashOut(cashOutAmount);
        uint256 afterCashOut = c.balances(actor);

        // General invariant: after CashOut, balance = beforeCashOut - cashOutAmount.
        // This invariant holds for the reference C for all inputs, but fails for the mutant M
        // whenever the second deposit (or any deposit after a first) overwrites previous balances.
        assertEq(afterCashOut, beforeCashOut - cashOutAmount);
    }
}

