pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 initial, uint256 deposit, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(initial > 0 && initial < type(uint256).max);
        vm.assume(deposit >= c.MinDeposit() && deposit < type(uint256).max);
        vm.assume(initial + deposit >= initial);

        // Establish a non-zero balance for actor via a prior Deposit
        vm.deal(actor, initial);
        vm.prank(actor);
        c.Deposit{value: initial}();
        uint256 balanceBefore = c.balances(actor);

        // Perform the Deposit under test
        vm.deal(actor, deposit);
        vm.prank(actor);
        c.Deposit{value: deposit}();
        uint256 balanceAfter = c.balances(actor);

        // Invariant: balance must increase by exactly the deposit amount
        assertTrue(balanceAfter == balanceBefore + deposit);
    }
}

