pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address actor, uint256 depositAmt, uint256 cashOutAmt) public {
        // Restrict actor to not be the C contract itself (could cause balance miscounts)
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        vm.assume(depositAmt >= c.MinDeposit());
        vm.assume(cashOutAmt > 0);
        // Prevent overflow in total deposit tracking
        vm.assume(depositAmt <= type(uint256).max / 3);

        // Fund actor with Ether for the deposit
        vm.deal(actor, depositAmt * 2);

        // Perform a Deposit from actor
        vm.prank(actor);
        c.Deposit{value: depositAmt}();

        // At this point actor has some balance in the contract
        uint256 balanceAfterDeposit = c.balances(actor);

        // CashOut only up to the current balance to avoid revert
        uint256 withdrawal = cashOutAmt % (balanceAfterDeposit + 1);

        // Perform CashOut
        vm.prank(actor);
        c.CashOut(withdrawal);

        uint256 finalBalance = c.balances(actor);

        // Invariant: After a deposit and a withdrawal, the balance MUST be the original balance
        // plus the deposit minus the withdrawal. Because the mutant resets the balance to 0 before
        // adding the deposit, any pre-existing balance (even from a prior test deposit) would be lost.
        // Here, the "pre-existing" balance is whatever actor had before this test started, which is 0.
        // So the correct final balance is depositAmt - withdrawal.
        // The mutant ends up with depositAmt - withdrawal when there was no prior balance, but the
        // invariant still holds for the *simple* case? No, the issue is subtle: the requirement says
        // the mutant resets the balance to 0 BEFORE adding. So if there IS a prior balance, it is
        // destroyed. To expose this, we need to create a non-zero prior balance. The test below does
        // two deposits to create a prior balance, then cashes out. The fuzzer explores all variants.
        //
        // Revised: We perform Deposit, then another Deposit (maybe from a different sender?).
        // Actually, the invariant works for ANY actor with ANY flow. Let's just let the fuzzer do
        // any sequence via the single entry point? The rules allow driving through CashOut only.
        // We'll simulate a prior balance by calling Deposit twice before cashout.
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address depositor, uint256 priorBalance, uint256 depositAmount) public {
        vm.assume(depositor != address(0));
        vm.assume(depositor != address(this));
        bound(depositAmount, 1 ether, type(uint256).max);
        bound(priorBalance, 0, type(uint256).max - depositAmount);

        if (priorBalance > 0) {
            vm.deal(depositor, priorBalance);
            vm.prank(depositor);
            c.Deposit{value: priorBalance}();
        }

        uint256 expected = priorBalance + depositAmount;
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        c.Deposit{value: depositAmount}();

        uint256 actual = c.balances(depositor);
        assertTrue(actual == expected);
    }
}
